import numpy as np

def kmeans(X, k, init, max_iter):
    X = np.asarray(X, float)
    C = np.asarray(init, float).copy()
    prev = None
    for _ in range(max_iter):
        d = ((X[:, None, :] - C[None, :, :]) ** 2).sum(axis=2)
        labels = d.argmin(axis=1)
        if prev is not None and (labels == prev).all():
            break
        for j in range(k):
            if (labels == j).any():
                C[j] = X[labels == j].mean(axis=0)
        prev = labels
    inertia = float(((X - C[labels]) ** 2).sum())
    return labels, np.round(C, 4), round(inertia, 4)

import numpy as np

def rbf_kernel_predict(X_sv, coef, b, gamma, x):
    X_sv = np.asarray(X_sv, float)
    x = np.asarray(x, float)
    k = np.exp(-gamma * ((X_sv - x) ** 2).sum(axis=1))
    return float(np.dot(coef, k) + b)
